// @ts-strict-ignore
import { IGatsbyImageData } from "gatsby-plugin-image";
import { LanguageHelper, isNonEmptyArray } from "../helpers";
import { Tag } from "../types";

export type RestaurantNode = {
  __typename?: string;
  contentful_id: string;
  node_locale: "sv" | "en";
  internalTitle: string;
  id: string;
  sortIndex?: number;
  title: string;
  preamble?: {
    preamble: string;
  };
  description?: {
    childMarkdownRemark: {
      html: string;
    };
  };
  shortDescriptionInList?: string;
  imageInList?: {
    file: {
      url: string;
    };
    gatsbyImageData?: IGatsbyImageData;
  };
  label?: string;
  tags?: Array<Tag>;
  restaurantPageLink?: {
    slug: string;
  };
  mapLink?: {
    id: string;
    title: string;
    smallDeviceTitle: string;
    internalLink: {
      slug: string;
    };
    externalUrl: string;
    openInNewTab: boolean;
    image: {
      file: {
        url: string;
      };
    };
    asset: {
      file: {
        url: string;
      };
    };
    icon: string;
  };
  externalPejLink?: string;
  foodTerminalId?: number;
};

export type Restaurant = {
  node: RestaurantNode;
};

type RestaurantData = {
  sv: Array<RestaurantNode>;
  en: Array<RestaurantNode>;
};

export type IRestaurantStore = {
  populateStore: (restaurants: Array<Restaurant>) => void;
  getRestaurantsByContentfulId: (contentfulId: string, locale?: string) => RestaurantNode | null;
  getRestaurantsByTerminalId: (terminalId: number, locale?: string) => RestaurantNode | null;
};

class RestaurantStore implements IRestaurantStore {
  restaurants: RestaurantData = {
    sv: [],
    en: [],
  };
  initialized = false;

  populateStore(restaurants: Array<Restaurant>): void {
    if (!isNonEmptyArray(restaurants) || this.initialized) {
      return;
    }

    restaurants.forEach((restaurant) => {
      this.restaurants[restaurant.node.node_locale] ??= [];
      this.restaurants[restaurant.node.node_locale].push(restaurant.node);
    });

    this.initialized = true;
  }

  getRestaurantsByContentfulId(
    contentfulId: string,
    locale = LanguageHelper.getCurrentLocale() as keyof RestaurantData,
  ): RestaurantNode {
    if (!this.initialized) {
      return null;
    }

    return this.restaurants[locale]?.find((restaurant) => restaurant.contentful_id === contentfulId) ?? null;
  }

  getRestaurantsByTerminalId(terminalId: number, locale = LanguageHelper.getCurrentLocale() as keyof RestaurantData) {
    if (!this.initialized) {
      return null;
    }

    return this.restaurants[locale]?.find((restaurant) => restaurant.foodTerminalId === terminalId) ?? null;
  }
}

const store = new RestaurantStore();
export default store;
